/**
 * OOXML package surgery for PPTX templates.
 *
 * pptxgenjs cannot read an existing presentation, so filling a corporate
 * template means editing the package directly: slide parts, their
 * relationships, the content-type map, and the `sldIdLst` in
 * `ppt/presentation.xml` must all stay consistent, or the file opens broken.
 *
 * The XML here is machine-generated by PowerPoint/Google Slides: one line, no
 * comments, stable element shapes. Patterns are therefore anchored tightly
 * rather than parsed with a general XML round-trip, which would reorder
 * attributes and risk breaking things Office is picky about.
 */
import { readFile, writeFile } from "node:fs/promises";
import JSZip from "jszip";
const PRESENTATION = "ppt/presentation.xml";
const PRESENTATION_RELS = "ppt/_rels/presentation.xml.rels";
const CONTENT_TYPES = "[Content_Types].xml";
const SLIDE_REL_TYPE = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide";
const NOTES_REL_TYPE = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/notesSlide";
const SLIDE_CONTENT_TYPE = "application/vnd.openxmlformats-officedocument.presentationml.slide+xml";
export class PptxError extends Error {
    constructor(message) {
        super(message);
        this.name = "PptxError";
    }
}
const escapeAttr = (s) => s.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
/** Escape text destined for an XML text node. */
export function escapeText(s) {
    return s
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
}
function relsPartFor(slidePart) {
    const slash = slidePart.lastIndexOf("/");
    return `${slidePart.slice(0, slash)}/_rels/${slidePart.slice(slash + 1)}.rels`;
}
export class PptxPackage {
    zip;
    presXml;
    relsXml;
    typesXml;
    overrides;
    constructor(zip, presXml, relsXml, typesXml) {
        this.zip = zip;
        this.presXml = presXml;
        this.relsXml = relsXml;
        this.typesXml = typesXml;
        this.overrides = new Map();
    }
    static async load(path) {
        let zip;
        try {
            zip = await JSZip.loadAsync(await readFile(path));
        }
        catch (err) {
            throw new PptxError(`cannot read ${path} as a PPTX package: ${err instanceof Error ? err.message : String(err)}`);
        }
        const read = async (name) => {
            const f = zip.file(name);
            if (!f)
                throw new PptxError(`${path}: missing required part ${name}`);
            return f.async("string");
        };
        return new PptxPackage(zip, await read(PRESENTATION), await read(PRESENTATION_RELS), await read(CONTENT_TYPES));
    }
    /** Slides in presentation order. */
    slides() {
        const list = /<p:sldIdLst>([\s\S]*?)<\/p:sldIdLst>/.exec(this.presXml)?.[1];
        if (list === undefined)
            throw new PptxError("presentation.xml has no <p:sldIdLst>");
        const refs = [];
        for (const m of list.matchAll(/<p:sldId\b[^>]*\bid="(\d+)"[^>]*\br:id="([^"]+)"[^>]*\/>/g)) {
            const [, sldId, rId] = m;
            if (sldId === undefined || rId === undefined)
                continue;
            refs.push({ part: this.partForRid(rId), sldId, rId });
        }
        return refs;
    }
    partForRid(rId) {
        const re = new RegExp(`<Relationship\\b[^>]*\\bId="${rId}"[^>]*\\bTarget="([^"]+)"[^>]*/>`);
        const target = re.exec(this.relsXml)?.[1];
        if (target === undefined)
            throw new PptxError(`no relationship ${rId} in ${PRESENTATION_RELS}`);
        return `ppt/${target.replace(/^\.\.\//, "").replace(/^\//, "")}`;
    }
    async xml(part) {
        const f = this.zip.file(part);
        if (!f)
            throw new PptxError(`missing part ${part}`);
        return f.async("string");
    }
    setXml(part, xml) {
        this.zip.file(part, xml);
    }
    /** Relationship targets declared by a part, keyed by relationship type. */
    async relsOf(part) {
        const relsPart = relsPartFor(part);
        const f = this.zip.file(relsPart);
        if (!f)
            return [];
        const xml = await f.async("string");
        const out = [];
        for (const m of xml.matchAll(/<Relationship\b([^>]*)\/>/g)) {
            const attrs = m[1] ?? "";
            const id = /\bId="([^"]+)"/.exec(attrs)?.[1];
            const type = /\bType="([^"]+)"/.exec(attrs)?.[1];
            const target = /\bTarget="([^"]+)"/.exec(attrs)?.[1];
            if (id && type && target)
                out.push({ id, type, target });
        }
        return out;
    }
    nextRid() {
        let max = 0;
        for (const m of this.relsXml.matchAll(/\bId="rId(\d+)"/g)) {
            const n = Number(m[1]);
            if (Number.isFinite(n) && n > max)
                max = n;
        }
        return `rId${max + 1}`;
    }
    nextSldId() {
        const list = /<p:sldIdLst>([\s\S]*?)<\/p:sldIdLst>/.exec(this.presXml)?.[1] ?? "";
        let max = 255;
        for (const m of list.matchAll(/\bid="(\d+)"/g)) {
            const n = Number(m[1]);
            if (Number.isFinite(n) && n > max)
                max = n;
        }
        return String(max + 1);
    }
    nextSlideName() {
        let max = 0;
        for (const name of Object.keys(this.zip.files)) {
            const m = /^ppt\/slides\/slide(\d+)\.xml$/.exec(name);
            if (m) {
                const n = Number(m[1]);
                if (Number.isFinite(n) && n > max)
                    max = n;
            }
        }
        return `ppt/slides/slide${max + 1}.xml`;
    }
    addOverride(part, contentType) {
        const partName = `/${part}`;
        if (this.overrides.has(partName))
            return;
        this.overrides.set(partName, true);
        this.typesXml = this.typesXml.replace("</Types>", `<Override PartName="${escapeAttr(partName)}" ContentType="${escapeAttr(contentType)}"/></Types>`);
    }
    removeOverride(part) {
        const partName = `/${part}`;
        this.overrides.delete(partName);
        const re = new RegExp(`<Override\\b[^>]*PartName="${partName.replace(/[/.]/g, "\\$&")}"[^>]*/>`);
        this.typesXml = this.typesXml.replace(re, "");
    }
    addPresentationRel(rId, type, target) {
        this.relsXml = this.relsXml.replace("</Relationships>", `<Relationship Id="${escapeAttr(rId)}" Type="${escapeAttr(type)}" Target="${escapeAttr(target)}"/></Relationships>`);
    }
    /**
     * Insert a copy of `part` immediately after it in presentation order.
     *
     * The clone deliberately drops the notesSlide relationship: a notes part
     * belongs to exactly one slide, and pointing two slides at it produces a
     * file that PowerPoint reports as needing repair.
     */
    async duplicate(part) {
        const xml = await this.xml(part);
        const newPart = this.nextSlideName();
        this.setXml(newPart, xml);
        // Same rIds as the source: relationship ids are scoped to their part.
        const sourceRels = await this.relsOf(part);
        const kept = sourceRels.filter((r) => r.type !== NOTES_REL_TYPE);
        const body = kept
            .map((r) => `<Relationship Id="${escapeAttr(r.id)}" Type="${escapeAttr(r.type)}" Target="${escapeAttr(r.target)}"/>`)
            .join("");
        this.zip.file(relsPartFor(newPart), `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${body}</Relationships>`);
        this.addOverride(newPart, SLIDE_CONTENT_TYPE);
        const rId = this.nextRid();
        this.addPresentationRel(rId, SLIDE_REL_TYPE, `slides/${newPart.slice("ppt/slides/".length)}`);
        const sldId = this.nextSldId();
        this.insertSldIdAfter(part, `<p:sldId id="${sldId}" r:id="${rId}"/>`);
        return newPart;
    }
    insertSldIdAfter(part, element) {
        const ref = this.slides().find((s) => s.part === part);
        if (!ref)
            throw new PptxError(`cannot insert after unknown slide ${part}`);
        const anchor = new RegExp(`(<p:sldId\\b[^>]*\\br:id="${ref.rId}"[^>]*/>)`);
        if (!anchor.test(this.presXml)) {
            throw new PptxError(`slide ${part} (${ref.rId}) is not present in sldIdLst`);
        }
        this.presXml = this.presXml.replace(anchor, `$1${element}`);
    }
    /** Remove a slide and everything only it referenced (its notes, its rels). */
    async remove(part) {
        const ref = this.slides().find((s) => s.part === part);
        if (!ref)
            return;
        const rels = await this.relsOf(part);
        for (const r of rels) {
            if (r.type !== NOTES_REL_TYPE)
                continue;
            const notesPart = `ppt/${r.target.replace(/^\.\.\//, "").replace(/^\//, "")}`;
            this.zip.remove(relsPartFor(notesPart));
            this.zip.remove(notesPart);
            this.removeOverride(notesPart);
        }
        this.presXml = this.presXml.replace(new RegExp(`<p:sldId\\b[^>]*\\br:id="${ref.rId}"[^>]*/>`), "");
        this.relsXml = this.relsXml.replace(new RegExp(`<Relationship\\b[^>]*\\bId="${ref.rId}"[^>]*/>`), "");
        this.removeOverride(part);
        this.zip.remove(relsPartFor(part));
        this.zip.remove(part);
    }
    /** Keep only the first slide of a contiguous run, returning the survivor. */
    async collapseRun(parts) {
        const [keep, ...drop] = parts;
        if (keep === undefined)
            throw new PptxError("collapseRun needs at least one slide");
        for (const p of drop)
            await this.remove(p);
        return keep;
    }
    async save(path) {
        this.zip.file(PRESENTATION, this.presXml);
        this.zip.file(PRESENTATION_RELS, this.relsXml);
        this.zip.file(CONTENT_TYPES, this.typesXml);
        const buf = await this.zip.generateAsync({
            type: "nodebuffer",
            compression: "DEFLATE",
            compressionOptions: { level: 6 },
        });
        await writeFile(path, buf);
    }
}
